{
  "cases": [
    {
      "id": "C1",
      "instrument_review": "Exact-grid scoring gives a defined outcome for the 100 puzzles. The reported 70% describes one run; repeatability and the basis for fair comparisons with other systems are not established.",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Missing reporting does not establish whether repeated-run testing occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "The tested system scored 70% in one reported run.",
          "reason": "One reported score provides no evidence of stability across runs."
        }
      ]
    },
    {
      "id": "C2",
      "instrument_review": "Exact-grid scoring supports reporting performance on the specified puzzles in this evaluation. The explicitly single evaluation leaves score consistency untested, limiting repeatable comparisons.",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Contradicted",
          "quote": "they ran the evaluation exactly once and did not repeat it",
          "reason": "The passage explicitly rules out repeated-run testing."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "they ran the evaluation exactly once and did not repeat it",
          "reason": "Absent repeated measurements, stability is unknown; it is not demonstrated to be false."
        }
      ]
    },
    {
      "id": "C3",
      "instrument_review": "The defined scoring and controlled repetitions support consistency for this system on these puzzles. The observed range meets the report's stability criterion, but does not establish consistency for other systems or conditions.",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings",
          "reason": "The passage documents repeated evaluations under unchanged conditions and reports their scores."
        },
        {
          "id": "stable",
          "label": "Supported",
          "quote": "Scores ranged from 69% to 71%. The report defines stable for this comparison as a range of at most two percentage points.",
          "reason": "The observed range meets the stated stability criterion."
        }
      ]
    },
    {
      "id": "C4",
      "instrument_review": "Controlled repetitions reveal substantial score variation despite defined exact-grid scoring. The findings fail the report's stability criterion, making the single 70% result an unreliable basis for consistent comparisons.",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings",
          "reason": "Repeated-run testing under unchanged conditions is explicitly documented."
        },
        {
          "id": "stable",
          "label": "Contradicted",
          "quote": "Scores ranged from 20% to 90%. The report defines stable for this comparison as a range of at most two percentage points.",
          "reason": "The reported variation explicitly exceeds the stated stability limit."
        }
      ]
    },
    {
      "id": "C5",
      "instrument_review": "Installation guidance helps users set up the benchmark but adds no evidence about score consistency. The 70% result remains a single reported observation with repeatability unspecified.",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Installation instructions do not resolve whether repeated-run testing occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "They report no additional evaluation results.",
          "reason": "The added documentation supplies no repeated scores supporting stability."
        }
      ]
    },
    {
      "id": "C6",
      "instrument_review": "The shared puzzle set, exact-grid scoring, and fixed instructions support the reported task-specific comparison, matching the intended use. Repeatability and resource comparability are unspecified, and cross-domain conclusions lack evidence.",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "A achieved a higher score on the evaluated grid puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "The narrow evaluation cannot establish relative general intelligence across domains."
        }
      ]
    },
    {
      "id": "C7",
      "instrument_review": "The scores support a comparison on the evaluated grid puzzles. The intended selection for general intelligence exceeds the supplied task coverage; stating that purpose supplies no evidence for broader interpretation. Repeatability and resource comparability are unspecified.",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "A performed better by the stated scoring rule in this evaluation."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "An intended cross-domain use does not establish that grid scores measure general intelligence."
        }
      ]
    },
    {
      "id": "C8",
      "instrument_review": "Initial test scores alone do not establish workshop benefits. The later preregistered randomized trial, blinded correctness checks, and reported uncertainty support choosing A for decision correctness in the studied workshop. Generalization beyond those conditions and effects on time or safety remain unestablished.",
      "probes": [
        {
          "id": "before",
          "label": "Not established",
          "quote": "Initially, only test scores were available.",
          "reason": "The initial evidence supplies no workshop comparison establishing improved real inspection decisions."
        },
        {
          "id": "after",
          "label": "Supported",
          "quote": "With A, 90% of decisions were correct; with B, 70%. The reported uncertainty interval for the difference was 12 to 28 percentage points.",
          "reason": "The randomized trial supports greater correctness with A under the studied workshop conditions, with an interval favoring A."
        },
        {
          "id": "safety",
          "label": "Not established",
          "quote": "Time and safety outcomes were not measured.",
          "reason": "Improved correctness does not establish an improvement in unmeasured safety outcomes."
        }
      ]
    }
  ],
  "closing_note": "No instructions required clarification. Missing evidence was distinguished from explicit contradiction, and conclusions were limited to each case's supplied conditions."
}
